classDiagram
    class ChatResponse {
        +string requestId
        +string conversationId
        +string status
    }

    class Message {
        +string id
        +string role
        +string content
        +string createdAt
    }

    class Usage {
        +int inputTokens
        +int outputTokens
        +int totalTokens
    }

    class Citation {
        +string title
        +string url
        +string snippet
    }

    ChatResponse "1" *-- "1" Message : message
    ChatResponse "1" *-- "1" Usage : usage
    Message "1" *-- "0..*" Citation : citations
